#!/usr/bin/env python3
"""Fetch Paul Graham essays and create an audiobook MP3."""

import html as html_lib
import os
import re
import subprocess
import sys
from typing import List

import requests


def fetch_html(url: str) -> str:
    result = subprocess.run(["curl", "-sL", url], capture_output=True, text=True)
    if result.returncode != 0:
        raise RuntimeError(f"curl failed for {url}: {result.stderr}")
    return result.stdout


def html_to_text(html: str) -> str:
    # Remove scripts/styles
    html = re.sub(r"(?is)<script[^>]*>.*?</script>", " ", html)
    html = re.sub(r"(?is)<style[^>]*>.*?</style>", " ", html)
    # Preserve paragraph breaks
    html = re.sub(r"(?i)<br\s*/?>", "\n", html)
    html = re.sub(r"(?i)</p>", "\n", html)
    # Strip tags
    html = re.sub(r"(?is)<[^>]+>", " ", html)
    text = html_lib.unescape(html)
    # Normalize whitespace
    text = re.sub(r"[\t\r ]+", " ", text)
    text = re.sub(r"\n\s*\n+", "\n\n", text)
    return text.strip()


def extract_essay_text(raw_text: str, title: str) -> str:
    lower = raw_text.lower()
    t = title.lower()
    start = lower.find(t)
    if start != -1:
        text = raw_text[start:]
    else:
        text = raw_text

    # Cut off translation links and footer noise if present
    cut_points = ["translations", "translation", "ImageJapanese Translation"]
    for cp in cut_points:
        idx = text.lower().find(cp.lower())
        if idx != -1:
            text = text[:idx]
            break

    # Remove common site noise
    text = re.sub(r"\bImage\b", " ", text)
    text = re.sub(
        r"Want to start a startup\? Get funded by Y Combinator\.",
        " ",
        text,
        flags=re.IGNORECASE,
    )

    # Collapse excessive whitespace
    text = re.sub(r"\s+", " ", text).strip()
    return text


def clean_text_for_tts(text: str) -> str:
    text = re.sub(r"http[s]?://\S+", "", text)
    text = re.sub(r"\[\d+\]", "", text)
    text = re.sub(r"[^\w\s.,!?;:'\"()-]", " ", text)
    text = re.sub(r"\s+", " ", text)
    return text.strip()


def chunk_text(text: str, max_chars: int) -> List[str]:
    sentences = re.split(r"(?<=[.!?])\s+", text)
    chunks: List[str] = []
    current = ""
    for sentence in sentences:
        if len(current) + len(sentence) + 1 <= max_chars:
            current += sentence + " "
        else:
            if current.strip():
                chunks.append(current.strip())
            current = sentence + " "
    if current.strip():
        chunks.append(current.strip())
    return chunks


def concatenate_audio(audio_files: List[str], output_path: str) -> bool:
    if not audio_files:
        return False

    list_file = "/tmp/audio_list.txt"
    with open(list_file, "w") as f:
        for path in audio_files:
            f.write(f"file '{path}'\n")

    result = subprocess.run(
        [
            "ffmpeg",
            "-y",
            "-f",
            "concat",
            "-safe",
            "0",
            "-i",
            list_file,
            "-c",
            "copy",
            output_path,
        ],
        capture_output=True,
    )

    for path in audio_files:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass
    try:
        os.unlink(list_file)
    except FileNotFoundError:
        pass

    return result.returncode == 0


def create_with_elevenlabs(text: str, output_path: str) -> bool:
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    if not api_key:
        return False

    voice_id = "21m00Tcm4TlvDq8ikWAM"  # Rachel
    chunks = chunk_text(text, max_chars=4500)
    audio_files: List[str] = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/pg_chunk_{i:03d}.mp3"
        response = requests.post(
            f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
            headers={
                "xi-api-key": api_key,
                "Content-Type": "application/json",
            },
            json={
                "text": chunk,
                "model_id": "eleven_turbo_v2_5",
                "voice_settings": {"stability": 0.5, "similarity_boost": 0.75},
            },
            timeout=120,
        )

        if response.status_code != 200:
            return False

        with open(chunk_file, "wb") as f:
            f.write(response.content)
        audio_files.append(chunk_file)

    return concatenate_audio(audio_files, output_path)


def create_with_openai(text: str, output_path: str) -> bool:
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        return False

    chunks = chunk_text(text, max_chars=4000)
    audio_files: List[str] = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/pg_chunk_{i:03d}.mp3"
        response = requests.post(
            "https://api.openai.com/v1/audio/speech",
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
            },
            json={
                "model": "tts-1",
                "input": chunk,
                "voice": "onyx",
                "response_format": "mp3",
            },
            timeout=120,
        )

        if response.status_code != 200:
            return False

        with open(chunk_file, "wb") as f:
            f.write(response.content)
        audio_files.append(chunk_file)

    return concatenate_audio(audio_files, output_path)


def create_with_gtts(text: str, output_path: str) -> bool:
    from gtts import gTTS

    chunks = chunk_text(text, max_chars=4500)
    audio_files: List[str] = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/pg_chunk_{i:03d}.mp3"
        tts = gTTS(text=chunk, lang="en", slow=False)
        tts.save(chunk_file)
        audio_files.append(chunk_file)

    return concatenate_audio(audio_files, output_path)


def create_audiobook(text: str, output_path: str) -> str:
    providers = [
        ("elevenlabs", create_with_elevenlabs),
        ("openai", create_with_openai),
        ("gtts", create_with_gtts),
    ]

    for name, fn in providers:
        try:
            if fn(text, output_path):
                return name
        except Exception:
            continue

    raise RuntimeError("All TTS providers failed")


def main() -> int:
    essays = [
        (
            "Do Things that Don't Scale",
            "https://www.paulgraham.com/ds.html",
        ),
        (
            "Founder Mode",
            "https://www.paulgraham.com/foundermode.html",
        ),
    ]

    parts = ["Paul Graham Essays."]
    for i, (title, url) in enumerate(essays, start=1):
        print(f"Fetching: {title}")
        html = fetch_html(url)
        raw_text = html_to_text(html)
        essay_text = extract_essay_text(raw_text, title)
        if len(essay_text) < 1000:
            raise RuntimeError(f"Content for {title} seems too short")
        parts.append(f"Chapter {i}: {title}. {essay_text}")

    combined = "\n\n".join(parts)
    clean = clean_text_for_tts(combined)

    output_path = "/root/audiobook.mp3"
    provider = create_audiobook(clean, output_path)
    print(f"Created audiobook with {provider}: {output_path}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
